CREATE TYPE public.app_role AS ENUM ('super_admin','admin','hod','faculty','student');
CREATE TYPE public.batch_status AS ENUM ('draft','active','completed','cancelled');
CREATE TYPE public.submission_status AS ENUM ('draft','submitted','under_review','hod_approved','admin_approved','rejected','returned','completed','cancelled');
CREATE TYPE public.field_type AS ENUM ('text','textarea','number','email','phone','date','time','datetime','select','multiselect','radio','checkbox','file','image','student_select','faculty_select','batch_select','hod_select');

CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', phone text, department text, staff_id text, avatar_url text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, role));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('super_admin','admin')) $$;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE first_user boolean; BEGIN INSERT INTO public.profiles(id,full_name,email) VALUES(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.email,'')); SELECT count(*)=0 INTO first_user FROM public.user_roles; INSERT INTO public.user_roles(user_id,role) VALUES(new.id,CASE WHEN first_user THEN 'super_admin'::public.app_role ELSE 'student'::public.app_role END); RETURN new; END; $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE POLICY "own profile read" ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY "staff read profiles" ON public.profiles FOR SELECT TO authenticated USING(public.is_staff(auth.uid()) OR public.has_role(auth.uid(),'hod') OR public.has_role(auth.uid(),'faculty'));
CREATE POLICY "own profile update" ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid());
CREATE POLICY "staff update profiles" ON public.profiles FOR UPDATE TO authenticated USING(public.is_staff(auth.uid()));
CREATE POLICY "read own roles" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_staff(auth.uid()) OR public.has_role(auth.uid(),'hod'));
CREATE POLICY "staff manage roles insert" ON public.user_roles FOR INSERT TO authenticated WITH CHECK(public.is_staff(auth.uid()));
CREATE POLICY "staff manage roles update" ON public.user_roles FOR UPDATE TO authenticated USING(public.is_staff(auth.uid()));
CREATE POLICY "staff manage roles delete" ON public.user_roles FOR DELETE TO authenticated USING(public.is_staff(auth.uid()));

CREATE TABLE public.courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, program text, department text, duration_months integer, description text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.courses TO authenticated; GRANT ALL ON public.courses TO service_role; ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
CREATE POLICY "all read courses" ON public.courses FOR SELECT TO authenticated USING(true); CREATE POLICY "staff write courses" ON public.courses FOR ALL TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE TABLE public.batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, course_id uuid REFERENCES public.courses(id) ON DELETE SET NULL, hod_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, start_date date, end_date date, capacity integer DEFAULT 60, status public.batch_status NOT NULL DEFAULT 'draft', remarks text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.batches TO authenticated; GRANT ALL ON public.batches TO service_role; ALTER TABLE public.batches ENABLE ROW LEVEL SECURITY;
CREATE POLICY "all read batches" ON public.batches FOR SELECT TO authenticated USING(true); CREATE POLICY "staff write batches" ON public.batches FOR ALL TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE TABLE public.batch_faculty (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.batches(id) ON DELETE CASCADE, faculty_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, UNIQUE(batch_id,faculty_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.batch_faculty TO authenticated; GRANT ALL ON public.batch_faculty TO service_role; ALTER TABLE public.batch_faculty ENABLE ROW LEVEL SECURITY;
CREATE POLICY "all read batch faculty" ON public.batch_faculty FOR SELECT TO authenticated USING(true); CREATE POLICY "staff write batch faculty" ON public.batch_faculty FOR ALL TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE TABLE public.students (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE, roll_no text NOT NULL UNIQUE, full_name text NOT NULL, email text, phone text, batch_id uuid REFERENCES public.batches(id) ON DELETE SET NULL, course_id uuid REFERENCES public.courses(id) ON DELETE SET NULL, admission_date date DEFAULT current_date, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.students TO authenticated; GRANT ALL ON public.students TO service_role; ALTER TABLE public.students ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read students" ON public.students FOR SELECT TO authenticated USING(public.is_staff(auth.uid()) OR public.has_role(auth.uid(),'hod') OR public.has_role(auth.uid(),'faculty') OR profile_id=auth.uid()); CREATE POLICY "staff write students" ON public.students FOR ALL TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE TABLE public.class_timings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.batches(id) ON DELETE CASCADE, day_of_week smallint NOT NULL CHECK(day_of_week BETWEEN 0 AND 6), start_time time NOT NULL, end_time time NOT NULL, subject text NOT NULL, faculty_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, room text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.class_timings TO authenticated; GRANT ALL ON public.class_timings TO service_role; ALTER TABLE public.class_timings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "all read timings" ON public.class_timings FOR SELECT TO authenticated USING(true); CREATE POLICY "staff write timings" ON public.class_timings FOR ALL TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));

CREATE TABLE public.forms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, description text, target_roles public.app_role[] NOT NULL DEFAULT '{faculty}', workflow_steps text[] NOT NULL DEFAULT '{hod,admin}', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.forms TO authenticated; GRANT ALL ON public.forms TO service_role; ALTER TABLE public.forms ENABLE ROW LEVEL SECURITY;
CREATE POLICY "all read forms" ON public.forms FOR SELECT TO authenticated USING(true); CREATE POLICY "staff write forms" ON public.forms FOR ALL TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE TABLE public.form_fields (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), form_id uuid NOT NULL REFERENCES public.forms(id) ON DELETE CASCADE, label text NOT NULL, field_key text NOT NULL, field_type public.field_type NOT NULL DEFAULT 'text', placeholder text, help_text text, is_required boolean NOT NULL DEFAULT false, options text[], default_value text, min_length integer, max_length integer, sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.form_fields TO authenticated; GRANT ALL ON public.form_fields TO service_role; ALTER TABLE public.form_fields ENABLE ROW LEVEL SECURITY;
CREATE POLICY "all read fields" ON public.form_fields FOR SELECT TO authenticated USING(true); CREATE POLICY "staff write fields" ON public.form_fields FOR ALL TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE TABLE public.form_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), form_id uuid NOT NULL REFERENCES public.forms(id) ON DELETE CASCADE, batch_id uuid REFERENCES public.batches(id) ON DELETE CASCADE, course_id uuid REFERENCES public.courses(id) ON DELETE CASCADE, faculty_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, valid_from date, valid_to date, is_active boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.form_rules TO authenticated; GRANT ALL ON public.form_rules TO service_role; ALTER TABLE public.form_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY "all read rules" ON public.form_rules FOR SELECT TO authenticated USING(true); CREATE POLICY "staff write rules" ON public.form_rules FOR ALL TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE TABLE public.form_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference_no text NOT NULL UNIQUE DEFAULT('SUB-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))), form_id uuid NOT NULL REFERENCES public.forms(id) ON DELETE CASCADE, submitted_by uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, batch_id uuid REFERENCES public.batches(id) ON DELETE SET NULL, class_timing_id uuid REFERENCES public.class_timings(id) ON DELETE SET NULL, student_id uuid REFERENCES public.students(id) ON DELETE SET NULL, data jsonb NOT NULL DEFAULT '{}'::jsonb, status public.submission_status NOT NULL DEFAULT 'draft', current_step text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.form_submissions TO authenticated; GRANT ALL ON public.form_submissions TO service_role; ALTER TABLE public.form_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read submissions" ON public.form_submissions FOR SELECT TO authenticated USING(submitted_by=auth.uid() OR public.is_staff(auth.uid()) OR public.has_role(auth.uid(),'hod')); CREATE POLICY "create own submissions" ON public.form_submissions FOR INSERT TO authenticated WITH CHECK(submitted_by=auth.uid()); CREATE POLICY "update submissions" ON public.form_submissions FOR UPDATE TO authenticated USING(submitted_by=auth.uid() OR public.is_staff(auth.uid()) OR public.has_role(auth.uid(),'hod')); CREATE POLICY "staff delete submissions" ON public.form_submissions FOR DELETE TO authenticated USING(public.is_staff(auth.uid()));
CREATE TABLE public.workflow_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES public.form_submissions(id) ON DELETE CASCADE, actor_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, actor_role text, action text NOT NULL, remarks text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.workflow_actions TO authenticated; GRANT ALL ON public.workflow_actions TO service_role; ALTER TABLE public.workflow_actions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read actions" ON public.workflow_actions FOR SELECT TO authenticated USING(public.is_staff(auth.uid()) OR public.has_role(auth.uid(),'hod') OR EXISTS(SELECT 1 FROM public.form_submissions s WHERE s.id=submission_id AND s.submitted_by=auth.uid())); CREATE POLICY "insert actions" ON public.workflow_actions FOR INSERT TO authenticated WITH CHECK(actor_id=auth.uid());
CREATE TABLE public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid REFERENCES public.form_submissions(id) ON DELETE CASCADE, storage_path text NOT NULL, file_name text NOT NULL, file_type text, file_size integer, uploaded_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.documents TO authenticated; GRANT ALL ON public.documents TO service_role; ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read documents" ON public.documents FOR SELECT TO authenticated USING(uploaded_by=auth.uid() OR public.is_staff(auth.uid()) OR public.has_role(auth.uid(),'hod')); CREATE POLICY "insert documents" ON public.documents FOR INSERT TO authenticated WITH CHECK(uploaded_by=auth.uid()); CREATE POLICY "delete documents" ON public.documents FOR DELETE TO authenticated USING(uploaded_by=auth.uid() OR public.is_staff(auth.uid()));
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, body text, link text, is_read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own notifications" ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY "staff create notifications" ON public.notifications FOR INSERT TO authenticated WITH CHECK(public.is_staff(auth.uid()) OR user_id=auth.uid()); CREATE POLICY "update own notifications" ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()); CREATE POLICY "delete own notifications" ON public.notifications FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, user_role text, action text NOT NULL, module text NOT NULL, record_id text, details jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "staff read audit" ON public.audit_logs FOR SELECT TO authenticated USING(public.is_staff(auth.uid())); CREATE POLICY "insert audit" ON public.audit_logs FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());

